import {jobs,mountPuzzle} from './practical.js?v=missions12';
import {createCampus} from './campus.js';
import {createHero} from './hero.js?v=missions12';
import {createGame} from './engine.js?v=missions12';
const root=document.querySelector('#experience'),key='kontur-intro-v1',ids=['security','frontend','sysadmin'];
let progress={name:'Даниил',done:[],role:null},hero,puzzle,screen='welcome',active=null,boss=false,bossStep=0,remaining=360,timer,last,playing=false;
try{const p=JSON.parse(localStorage.getItem(key));if(p&&typeof p.name==='string'&&Array.isArray(p.done)){progress={name:p.name.slice(0,22),done:[...new Set(p.done.filter(id=>ids.includes(id)))],role:ids.includes(p.role)?p.role:null};}}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(key,JSON.stringify(progress));}catch{document.querySelector('#announcement').textContent='Автосохранение недоступно в этом браузере.';}}
function clear(){window.scrollTo(0,0);hero?.dispose();hero=null;puzzle?.();puzzle=null;clearInterval(timer);playing=false;}
function chrome(content){root.innerHTML=`<header class="topbar"><a href="./" class="brand"><i>К</i>КОНТУР<span>ПЕРВЫЙ ДОСТУП</span></a><span class="chapter">ГЛАВА 01 / ТОЧКА ВХОДА</span><button id="soundless" class="small-btn">На весь экран ↗</button></header>${content}<footer class="bottom"><span><i></i> Учебная среда · все действия игровые</span><span>DEVLIFE / 2026</span></footer>`;document.querySelector('#soundless').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{document.querySelector('#announcement').textContent='Полноэкранный режим недоступен. Можно развернуть окно браузера.';}};}
function character(){hero=createHero(document.querySelector('#hero'));}
function welcome(){clear();screen='welcome';chrome(`<main class="welcome"><div class="intro-copy"><div class="eyebrow"><span class="line"></span> КОЛЛЕДЖ КОНТУР / ПЕРВЫЙ ДЕНЬ</div><h1>Первый<br><em>доступ.</em></h1><p>Пока ты просто студент.<br>Сегодня попробуешь три профессии<br>и найдёшь своё рабочее место.</p><div class="identity"><label for="name">ИМЯ ПЕРСОНАЖА</label><input id="name" maxlength="22" value="${esc(progress.name)}" autocomplete="off"></div><button class="primary" id="enter">Войти в аудиторию <span>↗</span></button><a class="continue" href="career.html?resume=1">Продолжить прежнюю карьеру →</a></div><div class="hero-stage"><div class="orbit o1"></div><div class="orbit o2"></div><span class="hero-coordinate">СТУДЕНТ / 001</span><img class="hero-fallback" src="assets/student.png" alt="Персонаж из твоей наработки"><canvas id="hero" aria-label="Анимированный трёхмерный студент"></canvas><div class="hero-caption"><span>СПЕЦИАЛЬНОСТЬ</span><strong>Ещё не определился</strong><i>●</i></div><div class="stage-floor"></div></div><div class="chapter-label">01<span>ПЕРВЫЙ<br>ДОСТУП</span></div></main>`);character();document.querySelector('#enter').onclick=()=>{progress.name=document.querySelector('#name').value.trim()||'Студент';save();hub();};}
function hub(){clear();screen='hub';chrome(`<main class="campus"><img class="campus-bg" src="assets/classroom.png" alt="Аудитория Контура из наработки"><canvas id="campus3d" aria-label="Трёхмерная аудитория колледжа"></canvas><div class="campus-shade"></div><div class="campus-title"><span class="eyebrow">КОЛЛЕДЖ / ПРАКТИКУМ 01</span><h1>Учебная<br><em>лаборатория.</em></h1><p>${esc(progress.name)}, выбери рабочее место.</p></div><div class="stations">${ids.map((id,i)=>`<button class="station station-${i} ${progress.done.includes(id)?'done':''}" data-station="${id}" style="--job:${jobs[id].color}"><span class="station-pin">${progress.done.includes(id)?'✓':jobs[id].icon}</span><span class="station-label"><small>0${i+1} / ${progress.done.includes(id)?'ПРОЙДЕНО':'ПРАКТИКА'}</small><strong>${jobs[id].name}</strong></span></button>`).join('')}</div><div class="mentor"><span class="mentor-avatar">МС</span><div><small>МАРИНА СЕРГЕЕВНА / КУРАТОР</small><p>«Здесь выбирают руками. Почини, собери, запусти — и почувствуй, что тебе ближе».</p></div><div class="hub-progress"><b>${progress.done.length}<span> / 3</span></b><small>ПРОФЕССИЙ ПОПРОБОВАНО</small></div><button class="primary" id="choose" ${!progress.done.length?'disabled':''}>${progress.done.length?'Выбрать свой путь →':'Сначала попробуй профессию'}</button></div></main>`);hero=createCampus(document.querySelector('#campus3d'));document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>practice(b.dataset.station));document.querySelector('#choose').onclick=choose;}
function practice(id,isBoss=false){clear();screen='practice';active=id;boss=isBoss;const job=jobs[id];chrome(`<main class="workbench"><div class="workbar"><button class="back" id="back">← ${boss?'Выйти из испытания':'В аудиторию'}</button><span>${boss?'ФИНАЛЬНЫЙ ЗАПУСК / '+(bossStep+1)+' ИЗ 3':'ПРАКТИКУМ / '+job.name.toUpperCase()}</span>${boss?'<strong class="boss-clock" id="clock">'+Math.ceil(remaining)+' сек</strong>':'<span class="live-dot">● ЖИВАЯ СРЕДА</span>'}</div><div class="task-heading"><div><span class="eyebrow">${boss?'ДЕМОНСТРАЦИЯ ЧЕРЕЗ ШЕСТЬ МИНУТ':id==='security'?'ПРАКТИЧЕСКАЯ РАБОТА / СЕТЕВОЙ АУДИТ':id==='frontend'?'ПРАКТИЧЕСКАЯ РАБОТА / ВЫПУСК ПРИЛОЖЕНИЯ':'ПРАКТИЧЕСКАЯ РАБОТА / 3D'}</span><h1>${job.title}</h1></div><p>${job.hint}</p></div><div id="puzzle"></div><div class="task-finish" id="finish"></div></main>`);document.querySelector('#back').onclick=()=>boss?choose():hub();puzzle=mountPuzzle(document.querySelector('#puzzle'),id,()=>{playing=false;clearInterval(timer);if(!boss&&!progress.done.includes(id)){progress.done.push(id);save();}document.querySelector('#finish').innerHTML=`<div><span class="eyebrow">${boss?'СИСТЕМА ВОССТАНОВЛЕНА':'ПРОФЕССИЯ ОПРОБОВАНА'}</span><strong>${boss?['Первый узел работает.','Ещё один шаг до запуска.','Демонстрация спасена!'][bossStep]:job.name+' — это уже твой опыт.'}</strong></div><button class="primary" id="next">${boss?(bossStep===2?'Получить первый оффер ↗':'Следующая система →'):'Вернуться в аудиторию →'}</button>`;document.querySelector('#next').onclick=()=>{if(!boss)hub();else if(bossStep===2)offer();else{bossStep++;practice(bossRoute()[bossStep],true);}};});if(boss){playing=true;last=performance.now();timer=setInterval(()=>{const now=performance.now(),dt=(now-last)/1000;last=now;if(document.hidden||!playing||document.querySelector('#puzzle')?.dataset.paused==='true')return;remaining=Math.max(0,remaining-dt);document.querySelector('#clock').textContent=Math.ceil(remaining)+' сек';if(remaining<=0)failed();},200);}}
function choose(){clear();screen='choose';chrome(`<main class="choice"><div class="choice-head"><button class="back" id="return">← Ещё попробовать</button><span class="eyebrow">ТВОЙ ПУТЬ / ТВОЁ РЕШЕНИЕ</span><h1>Что тебе<br><em>ближе?</em></h1><p>Это выбор интереса, а не оценка способностей.<br>Выбери направление, которое уже попробовал.</p></div><div class="choice-list">${ids.map((id,i)=>`<button data-role="${id}" class="role-choice ${progress.done.includes(id)?'available':''}" ${!progress.done.includes(id)?'disabled':''}><span class="role-symbol" style="color:${jobs[id].color}">${jobs[id].icon}</span><div><small>${progress.done.includes(id)?'ТВОЯ ПЕРВАЯ РАБОТА УЖЕ ПОЛУЧИЛАСЬ':'СНАЧАЛА ПОПРОБУЙ В АУДИТОРИИ'}</small><h2>${jobs[id].name}</h2></div><span>↗</span></button>`).join('')}</div></main>`);document.querySelector('#return').onclick=hub;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{progress.role=b.dataset.role;save();bossReady();});}
function bossRoute(){return [progress.role,...['sysadmin','security','frontend'].filter(id=>id!==progress.role)].slice(0,3);}
function bossReady(){clear();chrome(`<main class="interlude"><div class="alarm-orbit">!</div><span class="eyebrow">ПОСЛЕДНИЙ ШАГ ПЕРЕД СТАЖИРОВКОЙ</span><h1>Демо через<br><em>шесть минут.</em></h1><p>Восстанови три системы перед показом.<br>Первое задание — ${jobs[progress.role].name.toLowerCase()}.<br>Все три задания — как в практике.</p><button class="primary" id="launch">Я справлюсь. Начать →</button><button class="back" id="return">← Сменить направление</button></main>`);document.querySelector('#launch').onclick=()=>{remaining=360;bossStep=0;practice(bossRoute()[0],true);};document.querySelector('#return').onclick=choose;}
function failed(){clear();chrome(`<main class="interlude"><span class="eyebrow">ЭТО БЫЛ ПРОБНЫЙ ЗАПУСК</span><h1>Нужна ещё<br><em>одна попытка.</em></h1><p>Время вышло. Профессия и пройденные практики сохранены.</p><button class="primary" id="retry">Попробовать снова →</button><button class="back" id="return">Вернуться к практике</button></main>`);document.querySelector('#retry').onclick=bossReady;document.querySelector('#return').onclick=hub;}
function offer(){clear();chrome(`<main class="offer"><div class="offer-paper"><span class="eyebrow">КОНТУР / ПЕРВЫЙ ОФФЕР</span><span class="seal">✓</span><h1>${esc(progress.name)},<br><em>ты в команде.</em></h1><div class="offer-role"><small>ТВОЯ СПЕЦИАЛЬНОСТЬ</small><h2>${jobs[progress.role].name}</h2><span>JUNIOR · ПЕРВЫЙ РАБОЧИЙ ДЕНЬ</span></div><p>Практикум завершён. Дальше — студия,<br>карьера и твоя IT-компания.</p><button class="primary" id="career">Зайти в свою студию ↗</button><small class="save-note">Прежняя карьера сохранится отдельной резервной копией.</small></div></main>`);document.querySelector('#career').onclick=()=>{try{const previous=localStorage.getItem('devlife-v2');if(previous)localStorage.setItem('devlife-before-practical-'+Date.now(),previous);const s=createGame(progress.role,progress.name);Object.assign(s,{stage:'career',bossIndex:3,xp:40,score:100,money:700,intro:'practical',log:['Первый доступ: практическое испытание завершено. Получен оффер Junior.']});localStorage.setItem('devlife-v2',JSON.stringify(s));location.href='career.html?resume=1';}catch{document.querySelector('.save-note').textContent='Не удалось сохранить прогресс. Освободи место в хранилище браузера и повтори.';}};}
welcome();window.addEventListener('pagehide',()=>{save();clear();});

if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
